import {geometryDistance,bounds} from './geo.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>{try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`:'';}catch{return '';}};
const state={point:null,source:null,accuracy:null,time:null,radius:100,category:'all',view:'here',items:[],statuses:{},municipality:null,limit:40,request:0,loading:false};
const types={address:['Adresse','↗'],property:['Eiendom','▧'],protected:['Verneområde','♧'],nature:['Naturtype','♧'],culture:['Kulturminne','⌑']};
const names={address:'Adresser',property:'Eiendommer',nature:'Naturtyper',protected:'Verneområder',culture:'Kulturminner',municipality:'Kommune og fylke'};
const fmt=d=>d===0?'Her':d<1000?`${Math.round(d)} m`:`${(d/1000).toFixed(2).replace('.',',')} km`;
function notice(text){$('#notice').textContent=text;$('#notice').hidden=!text;}
function view(v){state.view=v;$$('.view').forEach(e=>e.hidden=e.id!==v);$$('[data-view]').forEach(e=>e.setAttribute('aria-selected',e.dataset.view===v));}
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
$$('[data-radius]').forEach(b=>b.onclick=()=>{state.radius=+b.dataset.radius;state.limit=40;$$('[data-radius]').forEach(e=>e.setAttribute('aria-pressed',e===b));renderNear();});
$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.limit=40;$$('[data-category]').forEach(e=>e.setAttribute('aria-pressed',e===b));renderNear();});
$('#more').onclick=()=>{state.limit+=40;renderNear();};
$('#help').onclick=()=>$('#about').showModal();$$('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
$('#coordinates').onsubmit=e=>{e.preventDefault();const lat=Number($('#latitude').value),lon=Number($('#longitude').value);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;lookup([lon,lat],'Manuelt valgt punkt');};
$('#example').onclick=()=>lookup([10.7387,59.9075],'Eksempel: Akershus festning');
$('#locate').onclick=()=>{if(!navigator.geolocation){notice('GPS er ikke tilgjengelig. Skriv inn koordinater under GPS-knappen.');return;}$('#locate').disabled=true;$('#locate').textContent='⌖ Finner posisjonen …';notice('');navigator.geolocation.getCurrentPosition(p=>lookup([p.coords.longitude,p.coords.latitude],'GPS-posisjon',p.coords.accuracy),e=>{busy(false);notice(e.code===1?'Posisjonstilgang ble avslått. Tillat posisjon i Safari/innstillinger, eller skriv inn koordinater.':e.code===3?'GPS brukte for lang tid. Prøv igjen utendørs, eller skriv inn koordinater.':'Kunne ikke finne posisjonen. Prøv igjen eller velg et sted manuelt.');},{enableHighAccuracy:true,timeout:20000,maximumAge:0});};
function busy(b){state.loading=b;$('#locate').disabled=b;$('#locate').textContent=b?'⌖ Henter stedsdata …':'⌖ Oppdater min posisjon';}
$('#copy-position').onclick=async()=>{if(!state.point){notice('Velg et sted før du kopierer koordinater.');return;}try{await navigator.clipboard.writeText(`${state.point[1].toFixed(6)}, ${state.point[0].toFixed(6)}`);$('#copy-position').textContent='Koordinater kopiert ✓';setTimeout(()=>$('#copy-position').textContent='Kopier koordinater',2000);}catch{notice(`Koordinater: ${state.point[1].toFixed(6)}, ${state.point[0].toFixed(6)}`);}};
async function json(url,signal){const timeout=AbortSignal.timeout(30000);const r=await fetch(url,{signal:signal?AbortSignal.any([signal,timeout]):timeout});if(!r.ok)throw Error(`HTTP ${r.status}`);const j=await r.json();if(j.error)throw Error(j.error.message||'Tjenestefeil');return j;}
const url=(base,p)=>`${base}?${new URLSearchParams(p)}`;
let activeController;
async function lookup(point,source,accuracy=null){activeController?.abort();activeController=new AbortController();const signal=activeController.signal,id=++state.request;Object.assign(state,{point,source,accuracy,time:new Date(),items:[],statuses:{},municipality:null,limit:40});busy(true);notice(accuracy>100?'GPS-nøyaktigheten er dårligere enn 100 meter. Treff nær eiendoms- og vernegrenser kan være usikre.':'');$('#position-label').textContent=source;$('#position-meta').textContent=`${point[1].toFixed(6)}° N · ${point[0].toFixed(6)}° Ø${accuracy!==null?` · Nøyaktighet ±${Math.round(accuracy)} m`:''} · ${state.time.toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'})}`;$('#latitude').value=point[1];$('#longitude').value=point[0];
if(point[1]<57||point[1]>81||point[0]<3||point[0]>36){notice('Punktet ligger utenfor det vanlige norske dekningsområdet. Norske datakilder kan gi få eller ingen treff.');}
const tasks={address:()=>addresses(point,signal),property:()=>parcels(point,signal),municipality:()=>json(url('https://ws.geonorge.no/kommuneinfo/v1/punkt',{nord:point[1],ost:point[0],koordsys:4258}),signal),protected:()=>arcgis(point,'vern',signal),nature:()=>arcgis(point,'naturtyper_nin',signal),culture:()=>culture(point,signal)};
Object.keys(tasks).forEach(k=>state.statuses[k]='loading');render();
await Promise.allSettled(Object.entries(tasks).map(async([key,fn])=>{try{const data=await fn();if(id!==state.request)return;if(key==='municipality')state.municipality=data;else state.items.push(...data);state.statuses[key]='ok';}catch(e){if(id!==state.request)return;state.statuses[key]='error';}if(id===state.request)render();}));if(id===state.request){busy(false);render();}}
async function addresses(p,signal){let items=[];for(let side=0;side<50;side++){const j=await json(url('https://ws.geonorge.no/adresser/v1/punktsok',{lat:p[1],lon:p[0],radius:1000,treffPerSide:1000,side}),signal);items.push(...(j.adresser||[]));if(items.length>=(j.metadata?.totaltAntallTreff??items.length))return items.map(a=>({key:`address:${a.kommunenummer}:${a.adressekode}:${a.adressetekst}`,type:'address',title:a.adressetekst,subtitle:`${a.postnummer} ${a.poststed}`,distance:a.meterDistanseTilPunkt,data:a}));}throw Error('For mange adresser');}
async function parcels(p,signal){let items=[];for(let side=1;side<=100;side++){const j=await json(url('https://api.kartverket.no/eiendom/v1/punkt',{ost:p[0],nord:p[1],koordsys:4258,radius:1000,treffPerSide:500,side}),signal);items.push(...(j.eiendom||[]));if(items.length>=(j.metadata?.totaltAntallTreff??items.length)){const unique=new Map();for(const a of items){const key=`property:${a.kommunenummer}:${a.gardsnummer}:${a.bruksnummer}:${a.festenummer}:${a.seksjonsnummer}`;const v={key,type:'property',title:`Gnr. ${a.gardsnummer??'–'} / bnr. ${a.bruksnummer??'–'}`,subtitle:`Kommune ${a.kommunenummer}${a.festenummer?` · Fnr. ${a.festenummer}`:''}${a.seksjonsnummer?` · Snr. ${a.seksjonsnummer}`:''}`,distance:a.meterFraPunkt,data:a};if(!unique.has(key)||v.distance<unique.get(key).distance)unique.set(key,v);}return [...unique.values()];}}throw Error('For mange eiendommer');}
async function arcgis(p,service,signal){const b=bounds(p,1020);let features=[];let offset=0;for(let page=0;page<100;page++){const j=await json(url(`https://kart.miljodirektoratet.no/arcgis/rest/services/${service}/MapServer/0/query`,{f:'geojson',where:'1=1',geometry:b.join(','),geometryType:'esriGeometryEnvelope',inSR:4326,spatialRel:'esriSpatialRelIntersects',outFields:'*',outSR:4326,returnGeometry:true,resultOffset:offset,resultRecordCount:1000,orderByFields:'OBJECTID'}),signal);features.push(...(j.features||[]));offset+=j.features?.length||0;if(!j.exceededTransferLimit&&!j.properties?.exceededTransferLimit&&j.features?.length<1000)break;if(!j.features?.length)throw Error('Ufullstendig kartdata');if(page===99)throw Error('For mange kartobjekter');}
return features.map(f=>{const a=f.properties,type=service==='vern'?'protected':'nature';return {key:`${type}:${a.OBJECTID}`,type,title:a.offisieltNavn||a.navn||a['Områdenavn']||a.Naturtype||'Registrert område',subtitle:type==='protected'?`Vern · ${a.verneform||'Registrert verneområde'}`:a.Naturtype||'Kartlagt naturtype',distance:geometryDistance(p,f.geometry),data:a,href:a.faktaark||a.Faktaark};}).filter(x=>x.distance<=1000);}
async function culture(p,signal){let items=[];const b=bounds(p,1020);const base='https://api.ra.no/LokaliteterEnkeltminnerOgSikringssoner/collections/lokaliteter/items';let next=url(base,{f:'json',bbox:b.join(','),limit:1000,'filter-lang':'cql2-text',filter:'område IS NOT NULL',properties:'id,område,navn,kulturminneId,lokalitetskategori,vernetype,linkKulturminnesøk,informasjon,synlig,oppdateringsdato'});for(let page=0;next&&page<100;page++){const j=await json(next,signal);items.push(...(j.features||[]));const n=j.links?.find(l=>l.rel==='next');next=n?new URL(n.href,next).href:null;if(next&&new URL(next).origin!=='https://api.ra.no')throw Error('Uventet neste side');if(page===99&&next)throw Error('For mange kulturminner');}
return items.map(f=>({key:`culture:${f.id}`,type:'culture',title:f.properties.navn||`Kulturminne ${f.id}`,subtitle:`${f.properties.lokalitetskategori==='L-ARK'?'Arkeologisk lokalitet':'Kulturminnelokalitet'} · ${f.properties.vernetype||'Ukjent vern'}`,distance:geometryDistance(p,f.geometry),data:f.properties,href:f.properties['linkKulturminnesøk']})).filter(x=>x.distance<=1000);}
function render(){renderHere();renderNear();}
function sourceText(key){return state.statuses[key]==='loading'?'Henter data …':state.statuses[key]==='error'?'Tjenesten kunne ikke nås. Oppdater posisjonen for å prøve igjen.':'Ingen registrerte treff ved punktet.';}
function card(label,body,badge=''){return `<article class="card"><div class="card-head"><span class="card-label">${label}</span>${badge?`<span class="badge">${badge}</span>`:''}</div>${body}</article>`;}
function renderHere(){if(!state.point)return;const a=state.items.filter(i=>i.type==='address').sort((a,b)=>a.distance-b.distance)[0],m=state.municipality;let html=card('ADRESSE & STED',`<h3 class="address-title">${a?esc(a.title):state.statuses.address==='ok'?'Ingen adresse innen 1 km':'Adresse ikke tilgjengelig'}</h3><p class="subtle">${m?esc(`${m.kommunenavn} kommune · ${m.fylkesnavn} fylke`):esc(sourceText('municipality'))}</p>${a?`<p class="subtle">Nærmeste registrerte adresse · ${fmt(a.distance)} fra punktet. Adressen kan tilhøre en annen eiendom.</p>`:`<p class="subtle">${esc(sourceText('address'))}</p>`}`,a?'NÆRMESTE ADRESSE':'');const parcels=state.items.filter(i=>i.type==='property'&&i.distance===0);html+=card('EIENDOM VED PUNKTET',parcels.length?parcels.map(i=>`<div class="parcel-numbers"><div><span>Gårdsnummer</span><strong>${esc(i.data.gardsnummer??'–')}</strong></div><div><span>Bruksnummer</span><strong>${esc(i.data.bruksnummer??'–')}</strong></div></div><p class="subtle">${esc(i.subtitle)}</p>`).join(''):`<p class="subtle">${esc(sourceText('property'))}</p>`,'MATRIKKELEN');html+=card('HVEM EIER EIENDOMMEN?',`<h3>Eieroppslag krever innlogging</h3><p class="subtle">Eierinformasjon er ikke hentet. Bruk kommune- og matrikkelnummeret over i Eiendomsregisteret.</p>${link('https://eiendomsregisteret.kartverket.no/','Åpne Eiendomsregisteret')}`,'IKKE TILKOBLET');for(const [type,title] of [['protected','VERNEOMRÅDE VED PUNKTET'],['nature','NATURTYPE VED PUNKTET'],['culture','KULTURMINNER VED PUNKTET']]){const rows=state.items.filter(i=>i.type===type&&i.distance===0);html+=card(title,rows.length?rows.map(i=>`<div class="mini-item"><button data-item="${esc(i.key)}">${esc(i.title)}</button><p class="subtle">${esc(i.subtitle)}</p></div>`).join(''):`<p class="subtle">${esc(sourceText(type))}</p>`);}
html+=`<p class="caption">Se «I nærheten» for avstander innen 100 m og 1 km. Treffene viser registrerte kartdata og kan være ufullstendige.</p>`;$('#here-content').innerHTML=html;bindItems($('#here-content'));}
function selectedItems(){return state.items.filter(i=>i.distance<=state.radius&&(state.category==='all'||state.category===i.type||(state.category==='nature'&&i.type==='protected'))).sort((a,b)=>a.distance-b.distance||a.title.localeCompare(b.title,'nb'));}
function renderNear(){if(!state.point)return;const list=selectedItems();$('#list-caption').textContent=`${list.length} treff innen ${state.radius===100?'100 m':'1 km'} · sortert etter luftlinjeavstand${state.loading?' · oppdateres …':''}`;$('#source-status').innerHTML=Object.entries(state.statuses).filter(([k])=>k!=='municipality').map(([k,s])=>`<p class="source-line ${s==='error'?'error':''}">${esc(names[k])}: ${s==='loading'?'henter …':s==='error'?'utilgjengelig – resultatene for denne kilden mangler':'hentet'}</p>`).join('');$('#results').innerHTML=list.length?list.slice(0,state.limit).map(i=>`<button class="result" data-item="${esc(i.key)}"><span class="result-icon ${i.type}">${types[i.type][1]}</span><span class="result-copy"><strong>${esc(i.title)}</strong><small>${esc(types[i.type][0])} · ${esc(i.subtitle)}</small></span><span class="distance">${fmt(i.distance)} ↗</span></button>`).join(''):`<div class="empty"><h3>${state.loading?'Henter treff …':'Ingen treff i denne visningen'}</h3><p>${state.loading?'Søker i offentlige datakilder.':'Prøv 1 km eller en annen kategori. Kontroller kildestatus over; manglende data er ikke det samme som ingen forekomster.'}</p></div>`;$('#more').hidden=list.length<=state.limit;bindItems($('#results'));}
function bindItems(parent){parent.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>showDetail(state.items.find(i=>i.key===b.dataset.item)));}
function showDetail(i){if(!i)return;const a=i.data;let fields=[];if(i.type==='property')fields=[['Kommunenummer',a.kommunenummer],['Gårdsnummer',a.gardsnummer],['Bruksnummer',a.bruksnummer],['Festenummer',a.festenummer],['Seksjonsnummer',a.seksjonsnummer],['Grensekvalitet',a.nøyaktighetsklasseteig]];if(i.type==='address')fields=[['Kommune',a.kommunenavn],['Poststed',a.poststed],['Gårdsnummer (adresse)',a.gardsnummer],['Bruksnummer (adresse)',a.bruksnummer]];if(i.type==='culture')fields=[['Kulturminne-ID',a.kulturminneId],['Vernetype',a.vernetype],['Synlig i terrenget',a.synlig===true?'Ja':a.synlig===false?'Nei':'Ukjent']];if(i.type==='protected')fields=[['Verneform',a.verneform],['Kommune',a.kommune],['Forvaltning',a.forvaltningsmyndighet]];if(i.type==='nature')fields=[['Naturtype',a.Naturtype],['Lokalitetskvalitet',a.Lokalitetskvalitet],['Tilstand',a.Tilstand],['Kartlagt',a.Kartleggingsår]];$('#detail-content').innerHTML=`<p class="eyebrow">${esc(types[i.type][0])} · ${fmt(i.distance)}</p><h2>${esc(i.title)}</h2><p>${esc(i.subtitle)}</p><dl class="detail-properties">${fields.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v??'Ikke oppgitt')}</dd></div>`).join('')}</dl>${a.informasjon?`<p>${esc(a.informasjon).replace(/\n/g,'<br>')}</p>`:''}${i.href?link(i.href,'Les i originalkilden'):''}${i.type==='property'?`<p>Eier er ikke hentet. Søk på kommunenummer og matrikkelnummer i Eiendomsregisteret.</p>${link('https://eiendomsregisteret.kartverket.no/','Åpne Eiendomsregisteret')}`:''}${i.type==='protected'&&a.verneforskrift?'<p>'+link(a.verneforskrift,'Se verneforskrift')+'</p>':''}<p class="subtle">Kilde: ${['nature','protected'].includes(i.type)?'Miljødirektoratet':i.type==='culture'?'Riksantikvaren':'Kartverket'}. Avstander og områdegrenser er omtrentlige.</p>`;$('#detail').showModal();}
addEventListener('offline',()=>notice('Du er uten nett. Appen kan åpnes, men nye data kan ikke hentes. Opplysninger fra denne økten er fortsatt synlige.'));addEventListener('online',()=>notice('Du er på nett igjen. Oppdater posisjonen for å hente nye data.'));
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


